style.css:
/* Este CSS tentará inverter a cor de QUALQUER imagem para branco em preto
   O seletor 'img' irá aplicar isso a todas as imagens na página.
   Substitua 'img' por um seletor mais específico se souber o ID ou Classe da imagem. */

img {
    /* Aplica a transformação de cores */
    filter: invert(1) grayscale(100%);
}

/* Se quiser um fundo preto para toda a página (além da inversão da imagem) */
body {
    background-color: #000 !important;
    color: #fff !important; /* Para garantir que o texto também seja branco */
}
